.gsr-s { display:flex; align-items:center; gap:10px; }
.gsr-s img { width:28px; height:28px; border-radius:50%; border:1px solid #dadce0; padding:4px; box-sizing:border-box; background:#fff; }
.gsr-s span { display:flex; flex-direction:column; line-height:1.3; }
.gsr-s b { font-size:14px; font-weight:400; color:#202124; }
.gsr-s small { font-size:12px; color:#4d5156; }
.gsr-s svg { width:16px; height:16px; color:#70757a; margin-left:4px; }
.gsr-t { margin:6px 0 4px; font-size:20px; line-height:1.3; color:#1a0dab; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.gsr-d { font-size:14px; line-height:1.58; color:#4d5156; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
.gsr-d b { color:#5f6368; }
.sx3 { grid-template-columns:minmax(0,1.15fr) minmax(0,1fr); }
.gsr-t { font-size:17px; }

:root { --ay-dark:#00456d; --ay-primary:#11a9e6; }
.slide-inner.insights { padding: 56px 72px; }
.slide-title.compact { margin-bottom: 28px; font-size: 32px; }
.airy .slide-title.compact { margin-bottom: 34px !important; }
.slide-inner.insights > * { width:100%; }
.rc2s { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; max-width:1040px; margin:8px auto 0; }
.rc2 { display:flex; align-items:flex-start; gap:14px; background:var(--bg-white); border:1px solid var(--tint-grey-10); border-radius:14px; padding:18px 20px; font-size:17px; line-height:1.4; color:var(--ay-dark); }
.rc2 > svg { flex:0 0 26px; width:26px; height:26px; color:var(--ay-primary); margin-top:2px; }
.rc2 em { display:block; font-style:normal; font-weight:700; font-size:13px; text-transform:uppercase; letter-spacing:.04em; color:var(--ay-primary); margin-bottom:4px; }
.rc2 { text-align:left; }
